head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.spacYN = "N"; //기업인수목적 회사 구분
scwin.vScrenID = "ULDSTF05324.xml";
scwin.chkRowIndex = 0;
scwin.hist_bz_procs_no = "";
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    var url = "/administrativeIssue.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchAdministrativeIssue" + "&DIV_IDX=" + DIV_IDX_ADMISU_LIST + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + scwin.vIsurCd;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};


// dialog 호출용 함수
// 예비심사청구제출기관 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.fn_search();
    //jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        img_Regist.setDisabled(true);
        img_Regist.src = "../img/btn_new_d.gif";
    } else {
        img_Regist.setDisabled(false);
        img_Regist.src = "../img/btn_new.gif";
    }
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vIsurCd; // 발행기관코드값
    arrPar[1] = txb_ISU_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts_List.getCellData(dts_List.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = scwin.vIsurCd; // 발행기관코드값
    arrPar[1] = txb_ISU_NM.getValue(); // 종목명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드
    arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값

};
scwin.fn_newpre_create_frame = async function(arg) {
    /*
    0:관리종목지정
    1:관리종목사유변경
    2:관리종목사유및상장폐지기준일변경
    3:상장폐지기준일변경
    4:관리종목지정해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_0", "../lstproc/ULDSTF05325.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정", 200, 50, 620, 400, "window");
            break;
        case "1":
            await $c.frame.CreateDialogFrame("DLG_1", "../lstproc/ULDSTF05326.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 사유변경", 200, 50, 620, 520, "window");
            break;
        case "4":
            await $c.frame.CreateDialogFrame("DLG_2", "../lstproc/ULDSTF05327.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 해제", 200, 50, 620, 450, "window");
            break;
    }

    //fn_search() ; // 다이얼로그 창이 닫히면 조회를 보낸다.
    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "관리종목지정내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Search_onclick = function() {
    if (scwin.vIsurCd != "") {
        scwin.fn_search();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_Close_onclick = function() {
    window.close();
};
scwin.img_Regist_onclick = function() {
    if (txb_ISU_CD.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
        return true;
    }
    if (cmb_RegistTyp.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistTyp.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame(cmb_RegistTyp.BindColVal, "");
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;

    // 관리종목지정업무구분코드 값 넘겨야함
    scwin.fn_newpre_create_frame(dts_List.getCellData(dts_List.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"));
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
};
scwin.btn_iSU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    //fn_PopFindIsu(fr_SecuGrpId);
    $c.lc.fn_PopFindIsuAll(scwin.fr_SecuGrpId); // jackal_11.05.12

};
